	[100616] = {
		id = 100616,
		lastTime = 2000,
		talkContent = 'หลังจากขับไล่กลุ่มวัยรุ่นเกเรออกไปและทำให้ฟุเอกกุบาดเจ็บหายดีขึ้น ฟุเอกกุแสดงความขอบคุณอย่างมาก พวกคุณตัดสินใจเก็บมันใส่โปเกบอลไว้ก่อน แล้วจะทำการรักษาเพิ่มเติมเมื่อการผจญภัยเสร็จสิ้น เหตุการณ์ช่วยเหลือฟุเอกกุจบลงแล้ว พวกคุณเก็บสัมภาระและมุ่งหน้าไปยังจุดหมายปลายทางที่แผนที่ในแผ่นหินระบุ...'
	},
	[100701] = {
		id = 100701,
		lastTime = 2000,
		talkContent = 'พวกคุณ finally มาถึงสถานที่ที่มีป้ายหินบอกทาง แต่รอบๆ เป็นทะเลทราย ไม่มีลักษณะของอาคารเลย สิ่งที่แปลกคือ ในกลางทะเลทรายมีเสาค้ำยืนอยู่หกต้น สีต่างๆ กัน สีเหล่านี้ทำให้พวกคุณรู้สึกคุ้นเคยอย่างแปลกๆ รู้สึกเหมือนเคยเห็นที่ไหนมาก่อน...'
	},
	[100703] = {
		id = 100703,
		lastTime = 2000,
		talkContent = 'หลังจากไขปริศนาในหินเรียบร้อยแล้ว พื้นดินเริ่มสั่นสะเทือนอย่างรุนแรง สิ่งบางอย่างเริ่มลอยขึ้นจากทรายไม่นานนัก ซากหินต่ำๆ ปรากฏขึ้นตรงหน้าพวกคุณ ภายในซากหินนั้นมีรูปปั้นเมนัสที่ประณีตตั้งอยู่ รูปปั้นนั้นเหมือนกับมีบางสิ่งที่สะท้อนแสงแดดและเปล่งประกายสีสันระยิบระยับ...'
