	[100801] = {
		id = 100801,
		lastTime = 2000,
		talkContent = 'ขณะที่พวกคุณเตรียมจะหยิบรูปปั้นออกมา เงามืดก็คลุมพวกคุณเหมือนกับแสงแดดถูกอะไรบางอย่างบังไว้ เมื่อพวกคุณเงยหน้าขึ้นไปดู ก็พบกับเรือบินขนาดใหญ่ที่ลอยอยู่เหนือพวกคุณ ทันทีที่พวกคุณเงยหน้าขึ้นไปในช่องว่างนั้น แขนกลเครื่องจักรหนึ่งก็ยื่นออกมาและหยิบรูปปั้นเมนัสจากซากหินไปอย่างรวดเร็ว แล้วก็เก็บกลับเข้าไปในเรือบินทันที'
